class Smartphone {
    String brand;
    int batteryLevel;

    void ring() {
        System.out.println(brand + " phone is ringing! Battery: " + batteryLevel + "%");
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("Smartphone blueprint created!");
    }
}

class Employee {
    String name;
    String department;
    double salary;

    void introduce() {
        System.out.println("Hello, I am " + name + " from " + department);
    }
}

public class Main {
    public static void main(String[] args) {
        System.out.println("Employee blueprint ready!");
    }
}
